/*
[演算法邏輯說明]
這是一個關於圖形遍歷的問題，目的是計算地圖上每種語言對應的「國家」（連通區域）數量。
1. 我們遍歷地圖上的每一個格子。
2. 如果遇到一個尚未訪問過的格子，就從該點開始進行深度優先搜尋 (DFS) 或廣度優先搜尋 (BFS)，將所有相鄰且語言相同的格子標記為已訪問。
3. 每開始一次搜尋，就代表該語言的一個新國家，對該語言的計數器加 1。
4. 最後，將結果依照國家數量降序排列；若數量相同，則依照語言字母升序排列。
*/

#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <algorithm>

using namespace std;

int H, W;
vector<string> grid;
vector<vector<bool>> visited;

void dfs(int r, int c, char lang) {
    if (r < 0 || r >= H || c < 0 || c >= W || visited[r][c] || grid[r][c] != lang)
        return;
    visited[r][c] = true;
    dfs(r + 1, c, lang);
    dfs(r - 1, c, lang);
    dfs(r, c + 1, lang);
    dfs(r, c - 1, lang);
}

struct LangCount {
    char lang;
    int count;
};

bool compareLang(const LangCount& a, const LangCount& b) {
    if (a.count != b.count)
        return a.count > b.count;
    return a.lang < b.lang;
}

int main() {
    int N;
    cin >> N;
    for (int t = 1; t <= N; ++t) {
        cin >> H >> W;
        grid.resize(H);
        visited.assign(H, vector<bool>(W, false));
        for (int i = 0; i < H; ++i) cin >> grid[i];

        map<char, int> counts;
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                if (!visited[i][j]) {
                    counts[grid[i][j]]++;
                    dfs(i, j, grid[i][j]);
                }
            }
        }

        vector<LangCount> result;
        for (auto const& [lang, count] : counts) {
            result.push_back({lang, count});
        }
        sort(result.begin(), result.end(), compareLang);

        cout << "World #" << t << endl;
        for (const auto& res : result) {
            cout << res.lang << ": " << res.count << endl;
        }
    }
    return 0;
}

